```kotlin
import java.util.PriorityQueue

data class Node(val x: Int, val y: Int, val step: Int)

val f = arrayOf(intArrayOf(0, 1), intArrayOf(1, 0), intArrayOf(0, -1), intArrayOf(-1, 0))

val vis = Array(110) { IntArray(110) }

fun bfs(l: Int, u: Int, xi: Int, yi: Int): Int {
    val q = PriorityQueue<Node>(compareBy { it.step })
    var e = Node(l, u, 0)
    q.add(e)
    vis[l][u] = 1
    while (q.isNotEmpty()) {
        e = q.poll()
        if (e.x == xi && e.y == yi) return e.step
        for (i in 0 until 4) {
            val tx = e.x + f[i][0]
            val ty = e.y + f[i][1]
            val tstep = e.step + 1
            if (tx < 0 || ty < 0) continue
            if (vis[tx][ty] != 0) continue
            vis[tx][ty] = 1
            q.add(Node(tx, ty, tstep))
        }
    }
    return -1
}

fun main() {
    val s = readLine()!!.trim()
    val len = s.length
    var x = 0
    var y = 0
    var xx = 0
    var yy = 0
    for (i in 0 until len) {
        when (s[i]) {
            'L' -> y--
            'R' -> y++
            'U' -> x--
            'D' -> x++
        }
        xx = minOf(xx, x)
        yy = minOf(yy, y)
    }
    xx = -xx
    yy = -yy
    for (i in 0 until 110) {
        for (j in 0 until 110) vis[i][j] = 1
    }
    x = xx
    y = yy
    for (i in 0 until len) {
        when (s[i]) {
            'L' -> y--
            'R' -> y++
            'U' -> x--
            'D' -> x++
        }
        vis[x][y] = 0
    }
    val ans = bfs(xx, yy, x, y)

    if (ans == len) println("OK") else println("BUG")
}
